<?php
declare(strict_types=1);session_start();require __DIR__.'/../config/bootstrap.php';if(empty($_SESSION['somba_admin']))json_response(['error'=>'Unauthorized'],401);
$action=$_GET['action']??'stats';$pdo=db();
try{switch($action){case 'stats':$o=(int)$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn();$r=(float)$pdo->query("SELECT COALESCE(SUM(amount),0) FROM orders WHERE payment_status='paid'")->fetchColumn();$p=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE payment_status='pending'")->fetchColumn();$d=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE delivery_status='delivered'")->fetchColumn();json_response(compact('o','r','p','d'));case 'products':$q=$pdo->query('SELECT p.*,g.name game FROM products p JOIN games g ON g.id=p.game_id ORDER BY p.id DESC');json_response(['products'=>$q->fetchAll()]);case 'games':json_response(['games'=>$pdo->query('SELECT * FROM games ORDER BY name')->fetchAll()]);case 'orders':$q=$pdo->query('SELECT o.*,p.name product,g.name game FROM orders o JOIN products p ON p.id=o.product_id JOIN games g ON g.id=p.game_id ORDER BY o.id DESC');json_response(['orders'=>$q->fetchAll()]);case 'users':json_response(['users'=>$pdo->query('SELECT id,email,role,created_at FROM users ORDER BY id DESC')->fetchAll()]);case 'payments':$q=$pdo->query("SELECT order_number,amount,currency,payment_status,maketou_reference,created_at FROM orders ORDER BY id DESC");json_response(['payments'=>$q->fetchAll()]);case 'save_product':if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['error'=>'POST required'],405);$b=json_decode(file_get_contents('php://input'),true)??[];$id=(int)($b['id']??0);$fields=['game_id','name','slug','provider','provider_sku','maketou_cart_id','price','currency','delivery_type','active'];$vals=[];foreach($fields as $f)$vals[$f]=$b[$f]??null;if($id){$set=implode(',',array_map(fn($f)=>"$f=?",$fields));$pdo->prepare("UPDATE products SET $set WHERE id=?")->execute([...array_values($vals),$id]);}else{$pdo->prepare('INSERT INTO products('.implode(',',$fields).') VALUES('.implode(',',array_fill(0,count($fields),'?')).')')->execute(array_values($vals));}json_response(['ok'=>true]);case 'toggle_product':$id=(int)($_POST['id']??0);$pdo->prepare('UPDATE products SET active=1-active WHERE id=?')->execute([$id]);json_response(['ok'=>true]);case 'delete_product':$id=(int)($_POST['id']??0);$pdo->prepare('DELETE FROM products WHERE id=?')->execute([$id]);json_response(['ok'=>true]);default:json_response(['error'=>'Unknown action'],400);}}catch(Throwable $e){json_response(['error'=>'Database operation failed'],500);}
